/**
 * Unit tests for SimpleRegression.getSumSquaredErrors().
 */
public class SimpleRegression_getSumSquaredErrors_TriageGen0Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testGetSumSquaredErrorsWithPerfectCorrelation() {
        SimpleRegression regression = new SimpleRegression();
        // Perfectly linear relationship: y = 2x + 1
        // x = [1, 2, 3], y = [3, 5, 7]
        regression.addData(1.0, 3.0);
        regression.addData(2.0, 5.0);
        regression.addData(3.0, 7.0);

        // For perfect correlation, SSE should be 0
        Assert.assertEquals(0.0, regression.getSumSquaredErrors(), DELTA);
    }








}

package org.apache.commons.math.stat.regression;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.DistributionFactory;
import org.apache.commons.math.distribution.TDistribution;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for SimpleRegression.getSumSquaredErrors().
 */
public class SimpleRegression_getSumSquaredErrors_TriageGen0Test {

    private static final double DELTA = 1e-10;



    @Test
    public void testGetSumSquaredErrorsWithNonPerfectCorrelation() {
        SimpleRegression regression = new SimpleRegression();
        // Data points: (1, 2), (2, 3), (3, 5)
        // x: 1, 2, 3 -> sumX=6, sumX2=14
        // y: 2, 3, 5 -> sumY=10, sumY2=4+9+25=38, sumXY=2+6+15=23
        // Slope (b) = (n*sumXY - sumX*sumY) / (n*sumX2 - (sumX)^2)
        // b = (3*23 - 6*10) / (3*14 - 36) = (69 - 60) / (42 - 36) = 9 / 6 = 1.5
        // Intercept (a) = (sumY - b*sumX) / n = (10 - 1.5*6) / 3 = (10 - 9) / 3 = 1/3
        // Predicted y: 1.5(1)+1/3 = 1.8333, 1.5(2)+1/3 = 3.3333, 1.5(3)+1/3 = 4.8333
        // Errors: (2-1.8333)^2 + (3-3.3333)^2 + (5-4.8333)^2
        // SSE = (1/6)^2 + (-1/3)^2 + (1/6)^2 = 1/36 + 4/36 + 1/36 = 6/36 = 1/6 = 0.16666666666666666

        regression.addData(1.0, 2.0);
        regression.addData(2.0, 3.0);
        regression.addData(3.0, 5.0);

        Assert.assertEquals(1.0/6.0, regression.getSumSquaredErrors(), DELTA);
    }






}

package org.apache.commons.math.stat.regression;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.DistributionFactory;
import org.apache.commons.math.distribution.TDistribution;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for SimpleRegression.getSumSquaredErrors().
 */
public class SimpleRegression_getSumSquaredErrors_TriageGen0Test {

    private static final double DELTA = 1e-10;





    @Test(expected = ArithmeticException.class)
    public void testGetSumSquaredErrorsWithZeroVarianceX() {
        SimpleRegression regression = new SimpleRegression();
        // If all x are the same, sumXX - (sumX)^2 / n = 0, leading to division by zero in the mathematical formula
        // However, the formula in the provided snippet is: sumYY - sumXY * sumXY / sumXX
        // If sumXX is 0 (which happens if all x are 0), it throws ArithmeticException
        regression.addData(0.0, 1.0);
        regression.addData(0.0, 2.0);

        // This triggers sumXY * sumXY / sumXX where sumXX is 0
        regression.getSumSquaredErrors();
    }




}

